// j2.cpp = geometry of k2.cpp + j2_body.cpp (generated by mkj2.py); agent n7-second
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <ctime>
#include <string>
#include <vector>
#include <algorithm>
#include <chrono>
#ifdef _WIN32
#include <direct.h>
#define MKDIR(p) _mkdir(p)
#define RMDIR(p) _rmdir(p)
#else
#include <sys/stat.h>
#include <unistd.h>
#define MKDIR(p) mkdir(p, 0777)
#define RMDIR(p) rmdir(p)
#endif
// returns false if the part is finished or claimed by another process
static bool claimPart(const char *out) {
    if (!out) return true;
    FILE *f = fopen(out, "r"); if (f) { fclose(f); return false; }
    return MKDIR((std::string(out) + ".claim").c_str()) == 0;
}
static void releasePart(const char *out) { if (out) RMDIR((std::string(out) + ".claim").c_str()); }
using namespace std;
typedef unsigned long long ull;

static const int K = 7, NV = 5040, NC = 720, INF = 1 << 28;
static int8_t PW[NV][K];
static int pidx[1 << 21];
static int clsOf[NV];
static uint16_t rowent[NV][6], rowcls[NV][6];
static uint16_t s3[NV][5], s4[NV][23];

static int codeOf(const int8_t *p) { int c = 0; for (int i = 0; i < K; i++) c = c * 8 + p[i]; return c; }
static int ew(const int8_t *u, const int8_t *v) {
    for (int t = 1; t < K; t++) { bool ok = true; for (int i = t; i < K; i++) if (u[i] != v[i - t]) { ok = false; break; } if (ok) return t; }
    return K;
}
static int sigma(int v) { int8_t w[K]; for (int i = 0; i < K - 1; i++) w[i] = PW[v][i + 1]; w[K - 1] = PW[v][0]; return pidx[codeOf(w)]; }
static int sigmaInv(int v) { int8_t w[K]; w[0] = PW[v][K - 1]; for (int i = 1; i < K; i++) w[i] = PW[v][i - 1]; return pidx[codeOf(w)]; }
static int tau2(int v) { int8_t w[K]; for (int i = 0; i < K - 2; i++) w[i] = PW[v][i + 1]; w[K - 2] = PW[v][0]; w[K - 1] = PW[v][K - 1]; return pidx[codeOf(w)]; }
static int rev(int v) { int8_t w[K]; for (int i = 0; i < K; i++) w[i] = PW[v][K - 1 - i]; return pidx[codeOf(w)]; }

static void buildGeometry() {
    int8_t p[16]; for (int i = 0; i < K; i++) p[i] = i;
    memset(pidx, -1, sizeof pidx);
    int n = 0;
    do { memcpy(PW[n], p, K); pidx[codeOf(p)] = n; n++; } while (next_permutation(p, p + K));
    if (n != NV) { fprintf(stderr, "perm count\n"); exit(2); }
    for (int v = 0; v < NV; v++) clsOf[v] = -1;
    int nc = 0;
    for (int v = 0; v < NV; v++) if (clsOf[v] < 0) { int w = v; for (int i = 0; i < K; i++) { clsOf[w] = nc; w = sigma(w); } if (w != v) { fprintf(stderr, "rotation\n"); exit(2); } nc++; }
    if (nc != NC) { fprintf(stderr, "class count %d\n", nc); exit(2); }
    for (int v = 0; v < NV; v++) { int e = v; for (int j = 0; j < 6; j++) { rowent[v][j] = e; rowcls[v][j] = clsOf[e]; e = tau2(e); } if (e != v) { fprintf(stderr, "tau2 order\n"); exit(2); }
        for (int j = 0; j < 6; j++) for (int i = 0; i < j; i++) if (rowcls[v][i] == rowcls[v][j]) { fprintf(stderr, "2-cycle classes\n"); exit(2); } }
    for (int g = 0; g < NV; g++) {
        int q = sigmaInv(g), n3 = 0, n4 = 0;
        for (int v = 0; v < NV; v++) {
            if (clsOf[v] == clsOf[q]) continue;
            int w = ew(PW[q], PW[v]);
            if (w == 3) { if (n3 >= 5) { fprintf(stderr, "s3 count\n"); exit(2); } s3[g][n3++] = v; }
            else if (w == 4) { if (n4 >= 23) { fprintf(stderr, "s4 count\n"); exit(2); } s4[g][n4++] = v; }
            else if (w < 3) { // weight 2 between classes is the door only
                if (!(w == 2 && v == tau2(g))) { fprintf(stderr, "light edge\n"); exit(2); } }
        }
        if (n3 != 5 || n4 != 23) { fprintf(stderr, "succ counts %d %d\n", n3, n4); exit(2); }
    }
}

// ---- joint statements J(p_1 .. p_n; V, W; B), written from the joint search of the proof of 5,900 (section 5.4 there; steps 1 to 6)
// usage: j2 TABFILE V W B RLO RHI GP DEPTH NPARTS PART OUTFILE|- piece ...      piece = S<s> or R
//   RLO, RHI: only rings with RLO <= holes <= RHI (0 96 = all)
//   gate: the kept prefixes of piece GP (1 or 2) with DEPTH rows are numbered in the order of the search; part
//   PART extends those with number % NPARTS == PART. Everything above the gate is counted in part 0 only.
//   counters: kept = prefixes whose successors are tried; tried = start vertices tried (1 for the first piece,
//   5040 for every later piece that is started, 5 or 23 per kept prefix and kind of link).

static const int HMAX = 96, RMAX = 220, WMAX = 200, NPMAX = 5;
static int PT[9][HMAX + 1], PRt[HMAX + 1];
static unsigned long long tabHash = 1469598103934665603ULL;
static void loadTables(const char *fn) {
    FILE *f = fopen(fn, "r"); if (!f) { fprintf(stderr, "cannot open %s\n", fn); exit(2); }
    static char line[1 << 16]; int seen = 0;
    while (fgets(line, sizeof line, f)) {
        for (char *c = line; *c; c++) if (*c != '\r' && *c != '\n') { tabHash ^= (unsigned char)*c; tabHash *= 1099511628211ULL; }
        char *col = strchr(line, ':'); if (!col) continue;
        int *dst; if (line[0] == 'R') { dst = PRt; seen |= 1 << 9; } else { int s = atoi(line); if (s < 0 || s > 8) continue; dst = PT[s]; seen |= 1 << s; }
        char *p = col + 1, *e; int n = 0;
        for (;;) { long v = strtol(p, &e, 10); if (e == p) break; if (n <= HMAX) dst[n] = (int)v; n++; p = e; }
        if (n != HMAX + 1) { fprintf(stderr, "a table row has %d entries, %d expected\n", n, HMAX + 1); exit(2); }
    }
    fclose(f);
    if (seen != 1023) { fprintf(stderr, "table rows missing\n"); exit(2); }
}

static int NP, Vt, Wt, Bt, RLO, RHI, GP, DEPTH; static ull NPARTS, PART;
static bool isRing[NPMAX]; static int maxLinks[NPMAX];
static int Best[NPMAX + 1][WMAX + 1];          // Best[i][w]: pieces i.. as single objects within weight w
static int X[NPMAX][9][WMAX + 1];              // X[i][u][w]: a continuation with at most u links and the later pieces within w
static const int NEG = -(1 << 28);

static void buildTables() {
    for (int w = 0; w <= Wt; w++) Best[NP][w] = 0;
    for (int i = NP - 1; i >= 0; i--) {
        for (int w = 0; w <= Wt; w++) {
            int b = NEG;
            if (isRing[i]) { for (int H = max(0, RLO); H <= min(min(RHI, HMAX), w); H++) if (Best[i + 1][w - H] > NEG) b = max(b, PRt[H] - H + Best[i + 1][w - H]); }
            else for (int t = 0; t <= maxLinks[i]; t++) for (int e = 0; e <= HMAX && e + 6 * t <= w; e++) if (Best[i + 1][w - e - 6 * t] > NEG) b = max(b, PT[t][e] - e - 5 * t + Best[i + 1][w - e - 6 * t]);
            Best[i][w] = b;
        }
        if (!isRing[i]) for (int u = 0; u <= maxLinks[i]; u++) for (int w = 0; w <= Wt; w++) {
            int b = NEG;
            for (int t = 0; t <= u; t++) for (int e = 0; e <= HMAX && e + 6 * t <= w; e++) if (Best[i + 1][w - e - 6 * t] > NEG) b = max(b, PT[t][e] - e - 5 * t + Best[i + 1][w - e - 6 * t]);
            X[i][u][w] = b;
        }
    }
}

static uint8_t Cm[NC], Um[NC];
static int shared_;
static int leftW[NPMAX], needV[NPMAX];
static int8_t ringCache[NPMAX][RMAX][HMAX + 8];
static int pathE[NPMAX][RMAX], pathL[NPMAX][RMAX];
static bool below;
static ull keptB, keptT, triedB, triedT, foundB, foundT, complB, complT, gateCount;
static FILE *flog;

static void nodeSeq(int i, int g, int r, int d, int t, int mx);
static void nodeRing(int i, int g, int r, int d, int v0);
static bool ringKeep(int i, int r, int d);

static inline bool wouldComplete(int i, int val, int wt) {
    if (wt > leftW[i]) return false;
    if (i == NP - 1) return val >= needV[i];
    return val + Best[i + 1][leftW[i] - wt] >= needV[i];
}
// bit k: a row with k holes after a prefix with d holes gives a prefix (r1 rows, tn links) that is kept or can be a whole piece
static inline unsigned seqMask(int i, int r1, int d, int tn, int mx) {
    unsigned m = 0; int s = maxLinks[i];
    for (int k = 0; k < 6; k++) {
        int val = r1 - d - k - 5 * tn, wt = d + k + 6 * tn, w3 = leftW[i] - wt;
        bool u = (val > mx && wouldComplete(i, val, wt))
              || (val >= 1 && w3 >= 0 && val + X[i][s - tn][w3] >= needV[i])
              || (tn < s && val - 5 >= 1 && w3 - 6 >= 0 && val - 5 + X[i][s - tn - 1][w3 - 6] >= needV[i]);
        if (u) m |= 1u << k;
    }
    return m;
}
static inline unsigned ringMask(int i, int r1, int d) {
    unsigned m = 0;
    for (int k = 0; k < 6; k++) {
        int d1 = d + k; if (d1 > HMAX) break;
        int8_t &c = ringCache[i][r1][d1];
        if (!c) c = ringKeep(i, r1, d1) ? 1 : 2;
        bool u = c == 1 || (r1 >= 2 && d1 >= RLO && d1 <= RHI && wouldComplete(i, r1 - d1, d1));
        if (u) m |= 1u << k;
    }
    return m;
}

static inline void tryVertex(int i, int v, int r, int d, int tn, int mx, int v0, unsigned mask) {
    if (below) triedB++; else triedT++;
    const uint16_t *rc = rowcls[v];
    int l = 0, sh = 0;
    if (r + 1 >= RMAX) { fprintf(stderr, "RMAX\n"); exit(2); }
    int lmax = mask ? 6 - __builtin_ctz(mask) : 0;
    for (; l < lmax; l++) {
        int c = rc[l];
        if (Cm[c]) break;
        if (Um[c]) { if (shared_ >= Bt) break; shared_++; sh++; }
        Cm[c] = 1;
        if (!(mask >> (5 - l) & 1)) continue;
        pathE[i][r] = v; pathL[i][r] = l + 1;
        if (isRing[i]) nodeRing(i, rowent[v][l], r + 1, d + 5 - l, v0);
        else nodeSeq(i, rowent[v][l], r + 1, d + 5 - l, tn, mx);
    }
    while (l > 0) { --l; Cm[rc[l]] = 0; }
    shared_ -= sh;
}

static void printObject(FILE *f, int upto, int r) {
    for (int i = 0; i <= upto; i++) { fprintf(f, " | piece %d:", i + 1); int n = (i == upto) ? r : -1;
        for (int j = 0; (n < 0 ? pathL[i][j] != 0 : j < n); j++) { fprintf(f, " "); for (int q = 0; q < K; q++) fprintf(f, "%d", PW[pathE[i][j]][q] + 1); fprintf(f, ":%d", pathL[i][j]); } }
    fprintf(f, "\n");
}

// the current prefix of piece i (r rows) is taken as the whole piece
static void complete(int i, int r, int val, int wt) {
    if (wt > leftW[i]) return;
    if (i == NP - 1) {
        if (val >= needV[i]) { if (below) foundB++; else foundT++;
            if (flog && (below || PART == 0)) { fprintf(flog, "FOUND"); printObject(flog, i, r); fflush(flog); } }
        return;
    }
    if (val + Best[i + 1][leftW[i] - wt] < needV[i]) return;
    if (!below && !(PART == 0 || i + 2 <= GP)) return;   // above the gate: only part 0 follows it, unless the gate lies in the next piece
    if (below) complB++; else complT++;
    for (int j = 0; j < r; j++) for (int l = 0; l < pathL[i][j]; l++) { int c = rowcls[pathE[i][j]][l]; Cm[c] = 0; Um[c]++; }
    int keepLen = pathL[i][r]; pathL[i][r] = 0;
    leftW[i + 1] = leftW[i] - wt; needV[i + 1] = needV[i] - val;
    if (isRing[i + 1]) memset(ringCache[i + 1], 0, sizeof ringCache[i + 1]);
    unsigned mask = isRing[i + 1] ? ringMask(i + 1, 1, 0) : seqMask(i + 1, 1, 0, 0, NEG);
    for (int v = 0; v < NV; v++) tryVertex(i + 1, v, 0, 0, 0, NEG, v, mask);
    pathL[i][r] = keepLen;
    for (int j = 0; j < r; j++) for (int l = 0; l < pathL[i][j]; l++) { int c = rowcls[pathE[i][j]][l]; Um[c]--; Cm[c] = 1; }
}

// returns true if this prefix is to be extended by this part
static inline bool gateAndCount(int i, int r) {
    if (below) { keptB++; return true; }
    if (i + 1 == GP && r == DEPTH) { ull id = gateCount++; if (id % NPARTS != PART) return false; keptB++; below = true; return true; }
    keptT++; return true;
}

static void nodeSeq(int i, int g, int r, int d, int t, int mx) {
    int val = r - d - 5 * t, wt = d + 6 * t;
    if (val > mx) complete(i, r, val, wt);           // step 2: a piece is a strict record
    int s = maxLinks[i], w3 = leftW[i] - wt;
    bool k3 = val >= 1 && w3 >= 0 && val + X[i][s - t][w3] >= needV[i];                               // steps 3, 4
    bool k4 = t < s && val - 5 >= 1 && w3 - 6 >= 0 && val - 5 + X[i][s - t - 1][w3 - 6] >= needV[i];
    if (!(k3 || k4)) return;
    bool wasBelow = below;
    if (!gateAndCount(i, r)) return;
    int mx2 = max(mx, val);
    if (k3) { unsigned m3 = seqMask(i, r + 1, d, t, mx2); for (int j = 0; j < 5; j++) tryVertex(i, s3[g][j], r, d, t, mx2, 0, m3); }
    if (k4) { unsigned m4 = seqMask(i, r + 1, d, t + 1, mx2); for (int j = 0; j < 23; j++) tryVertex(i, s4[g][j], r, d, t + 1, mx2, 0, m4); }
    below = wasBelow;
}

static bool ringKeep(int i, int r, int d) {
    int left = leftW[i], need = needV[i];
    for (int H = max(d, RLO); H <= min(min(left, RHI), HMAX); H++) {
        if (Best[i + 1][left - H] <= NEG) continue;
        int lo = max(r + 1, need + H - Best[i + 1][left - H]);
        int hi = min(PRt[H], r + PT[0][H - d]);
        if (d > 0) hi = min(hi, (r * H) / d);
        if (lo <= hi) return true;
    }
    return false;
}

static void nodeRing(int i, int g, int r, int d, int v0) {
    if (r >= 2 && d >= RLO && d <= RHI) { bool cl = false; for (int j = 0; j < 5; j++) if (s3[g][j] == v0) cl = true; if (cl) complete(i, r, r - d, d); }
    if (d > HMAX) return;
    int8_t &c = ringCache[i][r][d];
    if (!c) c = ringKeep(i, r, d) ? 1 : 2;             // step 5
    if (c != 1) return;
    bool wasBelow = below;
    if (!gateAndCount(i, r)) return;
    { unsigned mr = ringMask(i, r + 1, d); for (int j = 0; j < 5; j++) tryVertex(i, s3[g][j], r, d, 0, 0, v0, mr); }
    below = wasBelow;
}

// ---- ring table (PROOF_5899 section 8.2): no ring with HLO <= H <= HHI holes has more than PR(H) rows,
// given the chain table M = row 0. usage: j2 ringtab TABFILE HLO HHI DEPTH NPARTS PART OUTFILE|-
static int RT_lo, RT_hi;
static int8_t rtCache[RMAX][HMAX + 8];
static bool rtKeep(int r, int d) {
    for (int H = max(d, RT_lo); H <= RT_hi; H++) {
        int lo = max(r + 1, PRt[H] + 1);
        int hi = min(PT[0][H], r + PT[0][H - d]);
        if (d > 0) hi = min(hi, (r * H) / d);
        if (lo <= hi) return true;
    }
    return false;
}
static void rtNode(int g, int r, int d, int v0);
static inline void rtTry(int v, int r, int d, int v0) {
    if (below) triedB++; else triedT++;
    const uint16_t *rc = rowcls[v];
    int l = 0;
    if (r + 1 >= RMAX) { fprintf(stderr, "RMAX\n"); exit(2); }
    for (; l < 6; l++) {
        int c = rc[l];
        if (Cm[c]) break;
        Cm[c] = 1;
        pathE[0][r] = v; pathL[0][r] = l + 1;
        rtNode(rowent[v][l], r + 1, d + 5 - l, v0);
    }
    while (l > 0) { --l; Cm[rc[l]] = 0; }
}
static void rtNode(int g, int r, int d, int v0) {
    if (d > RT_hi) return;
    if (r >= 2 && d >= RT_lo && r > PRt[d]) { bool cl = false; for (int j = 0; j < 5; j++) if (s3[g][j] == v0) cl = true;
        if (cl) { if (below) foundB++; else foundT++; if (flog && (below || PART == 0)) { fprintf(flog, "FOUND ring rows %d holes %d", r, d); printObject(flog, 0, r); fflush(flog); } } }
    int8_t &c = rtCache[r][d];
    if (!c) c = rtKeep(r, d) ? 1 : 2;
    if (c != 1) return;
    bool wasBelow = below;
    if (!gateAndCount(0, r)) return;
    for (int j = 0; j < 5; j++) rtTry(s3[g][j], r, d, v0);
    below = wasBelow;
}
static int ringtabMain(int argc, char **argv) {
    if (argc < 9) { fprintf(stderr, "usage: j2 ringtab TABFILE HLO HHI DEPTH NPARTS PART OUTFILE|-\n"); return 2; }
    loadTables(argv[2]);
    RT_lo = atoi(argv[3]); RT_hi = atoi(argv[4]); DEPTH = atoi(argv[5]); NPARTS = strtoull(argv[6], 0, 10); PART = strtoull(argv[7], 0, 10);
    const char *out = strcmp(argv[8], "-") ? argv[8] : 0;
    if (RT_lo < 0 || RT_hi > HMAX || NPARTS < 1 || PART >= NPARTS || (NPARTS > 1 && DEPTH < 1)) { fprintf(stderr, "bad arguments\n"); return 2; }
    GP = 1; if (NPARTS == 1) { GP = 0; DEPTH = 0; }
    string tmp; if (out) { tmp = string(out) + ".tmp"; flog = fopen((string(out) + ".found").c_str(), "w"); }
    auto t0 = chrono::steady_clock::now();
    below = (NPARTS == 1);
    rtTry(0, 0, 0, 0);
    double sec = chrono::duration<double>(chrono::steady_clock::now() - t0).count();
    double cpu = (double)clock() / CLOCKS_PER_SEC;
    if (flog) { fclose(flog); if (foundB + (PART == 0 ? foundT : 0) == 0) remove((string(out) + ".found").c_str()); }
    FILE *f = out ? fopen(tmp.c_str(), "w") : stdout;
    if (!f) { fprintf(stderr, "cannot write\n"); return 2; }
    fprintf(f, "j2 statement: tables %016llx ring table, rings with %d..%d holes have at most PR rows\n", tabHash, RT_lo, RT_hi);
    fprintf(f, "gate: piece %d depth %d parts %llu gate_count %llu\n", GP, DEPTH, NPARTS, gateCount);
    fprintf(f, "part %llu kept %llu tried %llu found %llu pieces_completed %llu\n", PART, keptB, triedB, foundB, complB);
    fprintf(f, "above the gate (counted for part 0 only): kept %llu tried %llu found %llu pieces_completed %llu\n", keptT, triedT, foundT, complT);
    fprintf(f, "time: wall %.1f cpu %.1f\n", sec, cpu);
    fprintf(f, "END\n");
    if (out) { fclose(f); remove(out); if (rename(tmp.c_str(), out)) { fprintf(stderr, "rename failed\n"); return 2; } releasePart(out); }
    return 0;
}

int main(int argc, char **argv) {
    if (argc >= 9 && !strcmp(argv[1], "ringtab")) { if (strcmp(argv[8], "-") && !claimPart(argv[8])) return 0; }
    else if (argc >= 13 && strcmp(argv[11], "-") && !claimPart(argv[11])) return 0;
    buildGeometry();
    if (argc >= 2 && !strcmp(argv[1], "ringtab")) return ringtabMain(argc, argv);
    if (argc < 13) { fprintf(stderr, "usage: j2 TABFILE V W B RLO RHI GP DEPTH NPARTS PART OUTFILE|- piece ...\n"); return 2; }
    loadTables(argv[1]);
    Vt = atoi(argv[2]); Wt = atoi(argv[3]); Bt = atoi(argv[4]); RLO = atoi(argv[5]); RHI = atoi(argv[6]);
    GP = atoi(argv[7]); DEPTH = atoi(argv[8]); NPARTS = strtoull(argv[9], 0, 10); PART = strtoull(argv[10], 0, 10);
    const char *out = strcmp(argv[11], "-") ? argv[11] : 0;
    NP = argc - 12;
    string spec;
    if (NP > NPMAX || Wt > WMAX || Wt < 0) { fprintf(stderr, "too many pieces or W too large\n"); return 2; }
    for (int i = 0; i < NP; i++) { const char *p = argv[12 + i]; spec += (i ? " " : ""); spec += p;
        if (p[0] == 'R' && !p[1]) { isRing[i] = true; maxLinks[i] = 0; }
        else if (p[0] == 'S' && p[1] >= '0' && p[1] <= '8' && !p[2]) { isRing[i] = false; maxLinks[i] = p[1] - '0'; }
        else { fprintf(stderr, "bad piece %s\n", p); return 2; } }
    if (NPARTS < 1 || PART >= NPARTS || (NPARTS > 1 && (GP < 1 || GP > 2 || GP > NP || DEPTH < 1))) { fprintf(stderr, "bad parts\n"); return 2; }
    if (NPARTS == 1) { GP = 0; DEPTH = 0; }
    buildTables();
    string tmp; if (out) { tmp = string(out) + ".tmp"; flog = fopen((string(out) + ".found").c_str(), "w"); }
    auto t0 = chrono::steady_clock::now();
    leftW[0] = Wt; needV[0] = Vt; below = (NPARTS == 1);
    memset(ringCache, 0, sizeof ringCache);
    if (RHI > HMAX) RHI = HMAX;
    tryVertex(0, 0, 0, 0, 0, NEG, 0, isRing[0] ? ringMask(0, 1, 0) : seqMask(0, 1, 0, 0, NEG));     // step 1: the first piece starts at 1 2 .. 7
    double sec = chrono::duration<double>(chrono::steady_clock::now() - t0).count();
    double cpu = (double)clock() / CLOCKS_PER_SEC;
    if (flog) { fclose(flog); if (foundB + (PART == 0 ? foundT : 0) == 0) remove((string(out) + ".found").c_str()); }
    FILE *f = out ? fopen(tmp.c_str(), "w") : stdout;
    if (!f) { fprintf(stderr, "cannot write\n"); return 2; }
    fprintf(f, "j2 statement: tables %016llx J(%s; %d, %d; %d) rings %d..%d\n", tabHash, spec.c_str(), Vt, Wt, Bt, RLO, RHI);
    fprintf(f, "gate: piece %d depth %d parts %llu gate_count %llu\n", GP, DEPTH, NPARTS, gateCount);
    fprintf(f, "part %llu kept %llu tried %llu found %llu pieces_completed %llu\n", PART, keptB, triedB, foundB, complB);
    fprintf(f, "above the gate (counted for part 0 only): kept %llu tried %llu found %llu pieces_completed %llu\n", keptT, triedT, foundT, complT);
    fprintf(f, "time: wall %.1f cpu %.1f\n", sec, cpu);
    fprintf(f, "END\n");
    if (out) { fclose(f); remove(out); if (rename(tmp.c_str(), out)) { fprintf(stderr, "rename failed\n"); return 2; } releasePart(out); }
    return 0;
}
